type Kont<A, R> = (k: (a: A) => R) => R;

const fetchJson = <T,>(u: string): Kont<Response, Promise<T>> => (k) =>
  fetch(u).then(r => k(r));

// a missing continuation is now a type error, not a hang
const run = async (): Promise<string> => fetchJson<Message>('/api').then(m => m.body);

async function collect<T>(ids: number[], get: (id: number) => Promise<T>): Promise<T[]> {
  const out: T[] = [];
  for (const id of ids) out.push(await get(id));   // continuation threading, typed
  return out;
}
